      if (this.session.sheet() !== sheet) return;
      this.personInput.set('');
      this.shareInput.set('');
      this.fromInput.set('');
      this.toInput.set('');
      this.changed.emit(pools);
    } catch (e) {
      if (this.session.sheet() === sheet) this.error.set(refusal(e, 'Could not add this member.'));
    } finally {
      this.submitting = false;
